import { computed, defineComponent, h, inject, provide, ref, useId, type ComputedRef, type InjectionKey, type PropType } from 'vue';
import { getRadioState, radioGroupStyleKeys } from '../lib/core';
import type { RadioGroupOrientation } from '../lib/core';
import styles from './radio-group.module.scss';

interface RadioGroupContextValue {
	value: string;
	name: string;
	disabled: boolean;
	select: (value: string) => void;
}

type RadioGroupContext = ComputedRef<RadioGroupContextValue>;

const RadioGroupContextKey: InjectionKey<RadioGroupContext> = Symbol('tile-radio-group');

export const RadioGroup = defineComponent({
	name: 'RadioGroup',
	props: {
		modelValue: { type: String, default: undefined },
		defaultValue: { type: String, default: '' },
		orientation: {
			type: String as PropType<RadioGroupOrientation>,
			default: 'vertical',
		},
		name: { type: String, default: '' },
		disabled: { type: Boolean, default: false },
	},
	emits: ['update:modelValue', 'change'],
	setup(props, { emit, slots }) {
		const internalValue = ref(props.defaultValue);
		const currentValue = computed(() => (props.modelValue !== undefined ? props.modelValue : internalValue.value));

		const context = computed<RadioGroupContextValue>(() => ({
			value: currentValue.value,
			name: props.name,
			disabled: props.disabled,
			select: (next: string) => {
				if (props.disabled) {
					return;
				}
				if (props.modelValue === undefined) {
					internalValue.value = next;
				}
				emit('update:modelValue', next);
				emit('change', next);
			},
		}));

		provide(RadioGroupContextKey, context);

		return () =>
			h(
				'div',
				{
					class: styles[radioGroupStyleKeys.root],
					role: 'radiogroup',
					'aria-orientation': props.orientation,
					'data-orientation': props.orientation,
				},
				slots.default?.(),
			);
	},
});

export const RadioGroupItem = defineComponent({
	name: 'RadioGroupItem',
	props: {
		value: { type: String, required: true },
		disabled: { type: Boolean, default: false },
	},
	setup(props, { slots }) {
		const context = inject(RadioGroupContextKey);
		if (!context) {
			throw new Error('RadioGroupItem must be used within <RadioGroup>.');
		}

		const checked = computed(() => context.value.value === props.value);
		const state = computed(() => getRadioState(checked.value));
		const inputId = `tile-radio-${useId()}`;

		return () =>
			h('label', { class: styles[radioGroupStyleKeys.label], for: inputId }, [
				h('input', {
					id: inputId,
					type: 'radio',
					name: context.value.name,
					value: props.value,
					checked: checked.value,
					disabled: props.disabled || context.value.disabled,
					class: styles[radioGroupStyleKeys.input],
					onChange: () => {
						if (!checked.value) {
							context.value.select(props.value);
						}
					},
				}),
				h('span', { 'data-state': state.value, class: styles[radioGroupStyleKeys.item] }, [
					h('span', { class: styles[radioGroupStyleKeys.indicator] }, [h('span', { class: styles[radioGroupStyleKeys.dot] })]),
				]),
				...(slots.default?.() ?? []),
			]);
	},
});

export default RadioGroup;

@use '../../../styles/variables/colors' as *;

.root {
	display: grid;
	gap: $spacing-3;

	&[data-orientation='horizontal'] {
		grid-auto-flow: column;
		grid-auto-columns: max-content;
	}
}

.label {
	position: relative;
	display: inline-flex;
	flex-shrink: 0;
	cursor: pointer;
}

.input {
	position: absolute;
	inset: 0;
	width: 100%;
	height: 100%;
	margin: 0;
	opacity: 0;
	cursor: pointer;

	&:focus-visible + .item {
		border-color: var(--tile-radio-focus-border, #{$ring});
		box-shadow: var(--tile-radio-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
		outline: var(--tile-radio-focus-outline, none);
		outline-offset: var(--tile-radio-focus-offset, 0px);
	}

	&:disabled {
		cursor: not-allowed;
	}

	&:disabled + .item {
		cursor: not-allowed;
		opacity: 0.5;
	}
}

.item {
	display: inline-flex;
	width: 1rem;
	height: 1rem;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	border: var(--tile-radio-border-width, 1px) solid var(--tile-radio-border, #{$input});
	border-radius: $radius-full;
	background-color: var(--tile-radio-background, #{$background});
	color: var(--tile-radio-color, #{$primary});
	box-shadow: var(--tile-radio-shadow, none);
	transition:
		border-color $transition-fast,
		box-shadow $transition-fast,
		color $transition-fast;
	outline: none;

	&[data-state='checked'] {
		border-color: var(--tile-radio-checked-border, #{$primary});
		background-color: var(--tile-radio-checked-background, #{$background});
		color: var(--tile-radio-checked-color, #{$primary});
		box-shadow: var(--tile-radio-checked-shadow, none);
	}
}

.input:focus-visible + .item[data-state='checked'] {
	box-shadow: var(--tile-radio-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
}

.indicator {
	display: flex;
	width: 100%;
	height: 100%;
	align-items: center;
	justify-content: center;
}

.dot {
	width: 0.5rem;
	height: 0.5rem;
	border-radius: $radius-full;
	background-color: currentColor;
}
